-- Сектора города «spb» (1489 штук, 20.10.2026): id, вид воды и центр из tools/fishing-hex
-- (build_hex_city.mjs spb, предпросмотр map_spb.html). Углы шестиугольника считаются
-- здесь же по тем же формулам, что сетка приложения (web/lib/data/hexGrid.ts, hexCorners):
-- rx = 0.006219000° по долготе, ry = 0.003115382° по широте, углы через 60°, как у админских секторов.
-- Строки в territories — так же, как admin_add_territory: id, kind, lat, lng, corners.
-- Откат: удалить строки с id на «P» (пока на них нет уловов и владельцев): spb_ROLLBACK.
insert into public.territories (id, kind, lat, lng, corners, is_deleted)
select v.id, v.kind::public.territory_kind, v.lat, v.lng,
  (select jsonb_agg(jsonb_build_array(
            round((v.lat + 0.003115382 * sin(radians(60 * i)))::numeric, 6),
            round((v.lng + 0.006219000 * cos(radians(60 * i)))::numeric, 6)) order by i)
   from generate_series(0, 5) as i),
  false
